      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória no heap a cada frame dentro do método Update(), provocada por concatenação de strings em loop ('s += i.ToString()'), criação contínua de arrays ('new object[10000]') e chamadas repetitivas a 'GameObject.FindObjectsOfType<GameObject>()'. Essas operações geram mais de 6.7 MB de lixo por frame, forçando coletas do Garbage Collector que paralisam a CPU por 23.18 ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _sb;
        private MaterialPropertyBlock _propBlock;
        private static readonly int ColorProperty = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _sb = new StringBuilder(gcConcatIterations * 4);
            _propBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var collider = quad.GetComponent<Collider>();
                if (collider != null) Destroy(collider);
                quad.name = string.Concat("Overdraw_", i);
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _sb.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sb.Append(i);
                }
            }

            if (stressCpu)
            {
                // Cache ou substituição de FindObjectsOfType em runtime para evitar varredura da hierarquia e alocação de arrays
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor(ColorProperty, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, textos (strings) e novos arrays são objetos gerenciados. Sempre que você soma textos usando '+' ou cria um novo array com 'new', a Unity aloca um novo pedaço de memória no Heap. Quando essa memória enche, o Garbage Collector (o coletor de lixo) precisa pausar a execução inteira do seu jogo para recolher os pedaços que não estão mais sendo usados. Isso causa travamentos bruscos (engasgos ou stutters). Para evitar isso em jogos de alta performance, evite criar strings e coleções a cada frame; utilize StringBuilder ou reutilize instâncias em buffers pré-alocados. Além disso, 'renderer.material' duplica materiais na memória; substitua pelo uso de 'MaterialPropertyBlock' para alterar cores sem alocar memória extra."
    }
  ],
  "dicas_level_design": null
}

